-- ----------------------------
-- Table structure for `order`
-- ----------------------------
DROP TABLE IF EXISTS `order`;
CREATE TABLE `order` (
  `id` varchar(191) NOT NULL,
  `userId` varchar(191) NOT NULL,
  `subTotal` decimal(15,2) NOT NULL,
  `discountAmount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `shippingFee` decimal(15,2) NOT NULL DEFAULT 0.00,
  `totalPayment` decimal(15,2) NOT NULL,
  `paymentMethod` enum('VNPAY','MOMO','COD') NOT NULL,
  `paymentStatus` enum('PENDING','PAID','FAILED','REFUNDED') NOT NULL DEFAULT 'PENDING',
  `status` enum('PENDING','CONFIRMED','PACKED','SHIPPING','DELIVERED','COMPLETED','CANCELLED') NOT NULL DEFAULT 'PENDING',
  `voucherId` varchar(191) DEFAULT NULL,
  `shippingName` varchar(191) DEFAULT NULL,
  `shippingPhone` varchar(191) DEFAULT NULL,
  `shippingAddress` varchar(191) DEFAULT NULL,
  `note` text DEFAULT NULL,
  `trackingCode` varchar(191) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `order_userId_idx` (`userId`),
  KEY `order_status_idx` (`status`),
  KEY `order_voucherId_fkey` (`voucherId`),
  CONSTRAINT `order_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `user` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `order_voucherId_fkey` FOREIGN KEY (`voucherId`) REFERENCES `voucher` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `order_subtotal_non_negative` CHECK (`subTotal` >= 0),
  CONSTRAINT `order_discount_non_negative` CHECK (`discountAmount` >= 0),
  CONSTRAINT `order_shipping_non_negative` CHECK (`shippingFee` >= 0),
  CONSTRAINT `order_total_non_negative` CHECK (`totalPayment` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

