  `productId` varchar(191) NOT NULL,
  `content` text NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `privatenote_userId_productId_key` (`userId`,`productId`),
  KEY `privatenote_productId_fkey` (`productId`),
  CONSTRAINT `privatenote_productId_fkey` FOREIGN KEY (`productId`) REFERENCES `product` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `privatenote_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Records of privatenote
-- ----------------------------

-- ----------------------------
-- Table structure for `product`
-- ----------------------------
DROP TABLE IF EXISTS `product`;
CREATE TABLE `product` (
  `id` varchar(191) NOT NULL,
  `sku` varchar(191) NOT NULL,
  `name` varchar(191) NOT NULL,
  `brand` varchar(191) NOT NULL,
  `price` decimal(15,2) NOT NULL,
  `originalPrice` decimal(15,2) DEFAULT NULL,
  `stockQuantity` int(11) NOT NULL DEFAULT 0,
  `categoryId` varchar(191) DEFAULT NULL,
  `cpu` varchar(191) NOT NULL,
  `ram` varchar(191) NOT NULL,
  `ramGb` int(11) NOT NULL,
  `storage` varchar(191) NOT NULL,
  `storageGb` int(11) NOT NULL,
  `gpu` varchar(191) NOT NULL,
  `display` varchar(191) NOT NULL,
  `battery` varchar(191) DEFAULT NULL,
  `weight` varchar(191) DEFAULT NULL,
  `os` varchar(191) DEFAULT NULL,
  `ports` text DEFAULT NULL,
  `connectivity` varchar(191) DEFAULT NULL,
  `color` varchar(191) DEFAULT NULL,
  `warrantyMonths` int(11) NOT NULL DEFAULT 12,
  `isFeatured` tinyint(1) NOT NULL DEFAULT 0,
  `description` text DEFAULT NULL,
  `imageUrl` text DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  `viewCount` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `product_sku_key` (`sku`),
  KEY `product_brand_idx` (`brand`),
  KEY `product_categoryId_idx` (`categoryId`),
  CONSTRAINT `product_categoryId_fkey` FOREIGN KEY (`categoryId`) REFERENCES `category` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `product_stock_non_negative` CHECK (`stockQuantity` >= 0),
  CONSTRAINT `product_price_positive` CHECK (`price` > 0),
  CONSTRAINT `product_original_price_valid` CHECK (`originalPrice` is null or `originalPrice` >= 0),
  CONSTRAINT `product_ram_positive` CHECK (`ramGb` > 0),
  CONSTRAINT `product_storage_positive` CHECK (`storageGb` > 0),
  CONSTRAINT `product_warranty_non_negative` CHECK (`warrantyMonths` >= 0),
  CONSTRAINT `product_views_non_negative` CHECK (`viewCount` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Records of product
-- ----------------------------
INSERT INTO product VALUES ('00f23f97-04b8-43c3-8460-9ddde2067012', 'ASU-008', 'ASUS ROG Strix G16 G614JV i7-13650HX/16GB/512GB/RTX 4060/16\" 165Hz', 'ASUS', '34990000.00', '37990000.00', '7', 'bcbc7029-3eec-4097-a7cb-233ad485346e', 'Intel Core i7-13650HX (14 nhân 20 luồng, tối đa 4.9GHz)', '16GB DDR5 4800MHz (2 khe, tối đa 32GB)', '16', '512GB SSD M.2 PCIe Gen4 NVMe', '512', 'NVIDIA GeForce RTX 4060 8GB GDDR6, TGP 140W', '16 inch FHD+ (1920 x 1200), IPS, 165Hz, 3ms, 100% sRGB', '4 cell 90Wh', '2.50 kg', 'Windows 11 Home bản quyền', '1 x Thunderbolt 4, 1 x USB-C 3.2, 2 x USB-A 3.2, 1 x HDMI 2.1, 1 x RJ45 LAN, 1 x jack 3.5mm', 'Wi-Fi 6E, Bluetooth 5.3', 'Xám (Eclipse Gray)', '24', '0', 'ROG Strix G16 mang ngôn ngữ thiết kế Cyberpunk đặc trưng của Republic of Gamers với dải LED Aura Sync bao quanh thân máy. Keo tản nhiệt kim loại lỏng trên CPU và hệ thống tản nhiệt Tri-Fan giúp máy vận hành bền bỉ ở công suất cao.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Intel Core i7-13650HX (14 nhân 20 luồng, tối đa 4.9GHz), đi kèm 16GB DDR5 4800MHz (2 khe, tối đa 32GB) và ổ cứng 512GB SSD M.2 PCIe Gen4 NVMe. Cấu hình này đủ sức chiến mượt các tựa game AAA lẫn eSports, đồng thời xử lý tốt livestream, dựng video và các tác vụ nặng khác.\n\n## Card đồ họa\n\nNVIDIA GeForce RTX 4060 8GB GDDR6, TGP 140W. Card hỗ trợ công nghệ DLSS và Ray Tracing, tăng tốc khung hình khi chơi game và rút ngắn thời gian render, xuất video.\n\n## Màn hình\n\n16 inch FHD+ (1920 x 1200), IPS, 165Hz, 3ms, 100% sRGB. Tần số quét cao giúp mọi chuyển động mượt mà, mang lại lợi thế lớn trong các game bắn súng và đua xe tốc độ cao.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 2.50 kg, màu Xám (Eclipse Gray). Pin 4 cell 90Wh, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành Windows 11 Home bản quyền được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n1 x Thunderbolt 4, 1 x USB-C 3.2, 2 x USB-A 3.2, 1 x HDMI 2.1, 1 x RJ45 LAN, 1 x jack 3.5mm. Kết nối không dây: Wi-Fi 6E, Bluetooth 5.3.\n\n## Phù hợp với\n\nGame thủ, streamer, sinh viên công nghệ thông tin và những ai cần một cỗ máy hiệu năng cao cho cả giải trí lẫn công việc nặng.\n\n## Cam kết tại LAPSTORE\n\nSản phẩm chính hãng mới 100%, nguyên seal. Bảo hành 24 tháng theo tiêu chuẩn nhà sản xuất, 1 đổi 1 trong 15 ngày nếu có lỗi phần cứng. Miễn phí giao hàng toàn quốc, hỗ trợ cài đặt phần mềm trọn đời và trả góp 0% qua thẻ tín dụng.', '/images/products/asu-008.jpg', '2026-10-24 21:19:12.940', '2026-10-24 21:19:12.940', '0');
INSERT INTO product VALUES ('047c4cf0-9786-416c-ac7b-c2219f20c555', 'MSI-009', 'MSI Stealth 16 AI Studio A1VGG Core Ultra 9 185H/32GB/2TB/RTX 4070/16\" 240Hz', 'MSI', '69990000.00', '74990000.00', '2', 'bcbc7029-3eec-4097-a7cb-233ad485346e', 'Intel Core Ultra 9 185H (16 nhân 22 luồng, tối đa 5.1GHz, tích hợp NPU AI)', '32GB DDR5 5600MHz', '32', '2TB SSD M.2 PCIe Gen4 NVMe', '2048', 'NVIDIA GeForce RTX 4070 8GB GDDR6', '16 inch QHD+ (2560 x 1600), IPS, 240Hz, 100% DCI-P3', '4 cell 99.9Wh', '1.99 kg', 'Windows 11 Home bản quyền', '2 x Thunderbolt 4, 2 x USB-A 3.2, 1 x HDMI 2.1, 1 x RJ45 LAN, 1 x đầu đọc thẻ microSD, 1 x jack 3.5mm', 'Wi-Fi 7, Bluetooth 5.4', 'Xanh đen (Star Blue)', '24', '0', 'MSI Stealth 16 AI Studio là laptop gaming \'tàng hình\' với vỏ hợp kim magie-nhôm, dày chỉ 19.95mm và nặng dưới 2kg dù mang RTX 4070. Bàn phím SteelSeries RGB từng phím và loa Dynaudio cho trải nghiệm giải trí cao cấp.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Intel Core Ultra 9 185H (16 nhân 22 luồng, tối đa 5.1GHz, tích hợp NPU AI), đi kèm 32GB DDR5 5600MHz và ổ cứng 2TB SSD M.2 PCIe Gen4 NVMe. Cấu hình này đủ sức chiến mượt các tựa game AAA lẫn eSports, đồng thời xử lý tốt livestream, dựng video và các tác vụ nặng khác.\n\n## Card đồ họa\n\nNVIDIA GeForce RTX 4070 8GB GDDR6. Card hỗ trợ công nghệ DLSS và Ray Tracing, tăng tốc khung hình khi chơi game và rút ngắn thời gian render, xuất video.\n\n## Màn hình\n\n16 inch QHD+ (2560 x 1600), IPS, 240Hz, 100% DCI-P3. Tần số quét cao giúp mọi chuyển động mượt mà, mang lại lợi thế lớn trong các game bắn súng và đua xe tốc độ cao.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 1.99 kg, màu Xanh đen (Star Blue). Pin 4 cell 99.9Wh, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành Windows 11 Home bản quyền được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n2 x Thunderbolt 4, 2 x USB-A 3.2, 1 x HDMI 2.1, 1 x RJ45 LAN, 1 x đầu đọc thẻ microSD, 1 x jack 3.5mm. Kết nối không dây: Wi-Fi 7, Bluetooth 5.4.\n\n## Phù h