INSERT INTO product VALUES ('088065fe-b18c-4d82-afc9-43e17f7afc91', 'MSI-004', 'MSI Thin GF63 12UC i5-12450H/8GB/512GB/RTX 3050/15.6\" 144Hz', 'MSI', '15990000.00', '18490000.00', '23', 'bcbc7029-3eec-4097-a7cb-233ad485346e', 'Intel Core i5-12450H (8 nhân 12 luồng, tối đa 4.4GHz)', '8GB DDR4 3200MHz (2 khe, tối đa 64GB)', '8', '512GB SSD M.2 PCIe NVMe', '512', 'NVIDIA GeForce RTX 3050 4GB GDDR6', '15.6 inch Full HD (1920 x 1080), IPS, 144Hz', '3 cell 52.4Wh', '1.86 kg', 'Windows 11 Home bản quyền', '1 x USB-C 3.2, 3 x USB-A 3.2, 1 x HDMI 1.4, 1 x RJ45 LAN, 1 x jack 3.5mm', 'Wi-Fi 6, Bluetooth 5.2', 'Đen (Black)', '24', '0', 'MSI Thin GF63 là laptop gaming mỏng nhẹ nhất trong tầm giá, nặng dưới 1.9kg với mặt lưng nhôm phay xước. Card RTX 3050 kết hợp màn hình 144Hz đủ để chiến tốt các game eSports và học thiết kế cơ bản.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Intel Core i5-12450H (8 nhân 12 luồng, tối đa 4.4GHz), đi kèm 8GB DDR4 3200MHz (2 khe, tối đa 64GB) và ổ cứng 512GB SSD M.2 PCIe NVMe. Cấu hình này đủ sức chiến mượt các tựa game AAA lẫn eSports, đồng thời xử lý tốt livestream, dựng video và các tác vụ nặng khác.\n\n## Card đồ họa\n\nNVIDIA GeForce RTX 3050 4GB GDDR6. Card hỗ trợ công nghệ DLSS và Ray Tracing, tăng tốc khung hình khi chơi game và rút ngắn thời gian render, xuất video.\n\n## Màn hình\n\n15.6 inch Full HD (1920 x 1080), IPS, 144Hz. Tần số quét cao giúp mọi chuyển động mượt mà, mang lại lợi thế lớn trong các game bắn súng và đua xe tốc độ cao.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 1.86 kg, màu Đen (Black). Pin 3 cell 52.4Wh, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành Windows 11 Home bản quyền được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n1 x USB-C 3.2, 3 x USB-A 3.2, 1 x HDMI 1.4, 1 x RJ45 LAN, 1 x jack 3.5mm. Kết nối không dây: Wi-Fi 6, Bluetooth 5.2.\n\n## Phù hợp với\n\nGame thủ, streamer, sinh viên công nghệ thông tin và những ai cần một cỗ máy hiệu năng cao cho cả giải trí lẫn công việc nặng.\n