INSERT INTO product VALUES ('1fce6829-d869-454a-9aca-50d3b3343a3d', 'HPQ-005', 'HP Spectre x360 14-eu0000 Core Ultra 7 155H/32GB/1TB/14\" 2.8K OLED', 'HP', '44990000.00', '49990000.00', '3', '54ee350b-95fb-436d-a6ec-b333bb394258', 'Intel Core Ultra 7 155H (16 nhân 22 luồng, tối đa 4.8GHz)', '32GB LPDDR5x 7467MHz', '32', '1TB SSD M.2 PCIe Gen4 NVMe', '1024', 'Intel Arc Graphics', '14 inch 2.8K OLED (2880 x 1800), 120Hz, cảm ứng, 100% DCI-P3, 500 nits HDR', '4 cell 68Wh', '1.44 kg', 'Windows 11 Home bản quyền', '2 x Thunderbolt 4, 1 x USB-A 3.2, 1 x jack 3.5mm', 'Wi-Fi 7, Bluetooth 5.4', 'Đen (Nightfall Black)', '12', '0', 'Spectre x360 14 là tuyệt tác thiết kế của HP với các góc cạnh vát kim cương, viền mạ vàng đồng và touchpad haptic lớn nhất phân khúc. Bút sạc lại và túi da đi kèm hoàn thiện trải nghiệm cao cấp.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Intel Core Ultra 7 155H (16 nhân 22 luồng, tối đa 4.8GHz), đi kèm 32GB LPDDR5x 7467MHz và ổ cứng 1TB SSD M.2 PCIe Gen4 NVMe. Cấu hình cân bằng giữa hiệu năng và thời lượng pin: khởi động nhanh, vận hành mát và êm, đủ mạnh cho công việc văn phòng lẫn sáng tạo nhẹ.\n\n## Card đồ họa\n\nIntel Arc Graphics. Đồ họa tích hợp đủ để xem phim 4K, chỉnh sửa ảnh cơ bản và chơi các game nhẹ.\n\n## Màn hình\n\n14 inch 2.8K OLED (2880 x 1800), 120Hz, cảm ứng, 100% DCI-P3, 500 nits HDR. Tấm nền OLED cho màu đen sâu tuyệt đối, độ tương phản cực cao và màu sắc rực rỡ, rất phù hợp xem phim và chỉnh sửa hình ảnh.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 1.44 kg, màu Đen (Nightfall Black). Pin 4 cell 68Wh, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành Windows 11 Home bản quyền được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n2 x Thunderbolt 4, 1 x USB-A 3.2, 1 x jack 3.5mm. Kết nối không dây: Wi-Fi 7, Bluetooth 5.4.\n\n## Phù hợp với\n\nNgười thường xuyên di chuyển, làm việc tại quán cà phê, sinh viên và dân văn phòng yêu thích sự gọn nhẹ, thời trang.\n\n## Cam kết tại LAPSTORE\n\nSản phẩm chính hãng mới 100%, nguyên seal. Bảo hành 12 tháng theo tiêu chuẩn nhà sản xuất, 1 đổi 1 trong 15 ngày nếu có lỗi phần cứng. Miễn phí giao hàng toàn quốc, hỗ trợ cài đặt phần mềm trọn đời và trả góp 0% qua thẻ tín dụng.', '/images/products/hpq-005.jpg', '2026-10-24 21:19:13.120', '2026-10-24 21:19:13.120', '0');
INSERT INTO product VALUES ('24475cde-791e-4c01-ad9f-389931371574', 'LEN-003', 'Lenovo Yoga Slim 7 14IMH9 Core Ultra 7 155H/32GB/1TB/14\" 2.8K OLED 120Hz', 'Lenovo', '29990000.00', '32990000.00', '6', '54ee350b-95fb-436d-a6ec-b333bb394258', 'Intel Core Ultra 7 155H (16 nhân 22 luồng, tối đa 4.8GHz)', '32GB LPDDR5x 7467MHz', '32', '1TB SSD M.2 PCIe Gen4 NVMe', '1024', 'Intel Arc Graphics', '14 inch 2.8K OLED (2880 x 1800), 120Hz, 100% DCI-P3, Dolby Vision, VESA DisplayHDR True Black 500', '4 cell 70Wh', '1.39 kg', 'Windows 11 Home bản quyền', '2 x Thunderbolt 4, 1 x USB-A 3.2, 1 x HDMI 2.1, 1 x jack 3.5mm', 'Wi-Fi 6E, Bluetooth 5.3', 'Xám (Luna Grey)', '24', '0', 'Yoga Slim 7 là ultrabook cao cấp của Lenovo với màn hình OLED 2.8K 120Hz hỗ trợ Dolby Vision và loa Dolby Atmos – lý tưởng cho người vừa làm việc vừa giải trí, xem phim chất lượng cao khi di chuyển.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Intel Core Ultra 7 155H (16 nhân 22 luồng, tối đa 4.8GHz), đi kèm 32GB LPDDR5x 7467MHz và ổ cứng 1TB SSD M.2 PCIe Gen4 NVMe. Cấu hình cân bằng giữa hiệu năng và thời lượng pin: khởi động nhanh, vận hành mát và êm, đủ mạnh cho công việc văn phòng lẫn sáng tạo nhẹ.\n\n## Card đồ họa\n\nIntel Arc Graphics. Đồ họa tích hợp đủ để xem phim 4K, chỉnh sửa ảnh cơ bản và chơi các game nhẹ.\n\n## Màn hình\n\n14 inch 2.8K OLED (2880 x 1800), 120Hz, 100% DCI-P3, Dolby Vision, VESA DisplayHDR True Black 500. Tấm nền OLED cho màu đen sâu tuyệt đối, độ tương phản cực cao và màu sắc rực rỡ, rất phù hợp xem phim và chỉnh sửa hình ảnh.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 1.39 kg, màu Xám (Luna Grey). Pin 4 cell 70Wh, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành Windows 11 Home bản quyền được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n2 x Thunderbolt 4, 1 x USB-A 3.2, 1 x HDMI 2.1, 1 x jack 3.5mm. Kết nối không dây: Wi-Fi 6E, Bluetooth 5.3.\n\n## Phù hợp với\n\nNgười thường xuyên di chuyển, làm việc tại quán cà phê, sinh viên và dân văn phòng yêu thích sự gọn nhẹ, thời trang.\n\n## Cam kết tại LAPSTORE\n\nSản phẩm chính hãng mới 100%, nguyên seal. Bảo hành 24 tháng theo tiêu chuẩn nhà sản xuất, 1 đổi 1 trong 15 ngày nếu có lỗi phần cứng. Miễn phí giao hàng toàn quốc, hỗ trợ cài đặt phần mềm trọn đời và trả góp 0% qua thẻ tín dụng.', '/images/products/len-003.jpg', '2026-10-24 21:19:12.983', '2026-10-24 21:19:12.983', '0');
INSERT INTO product VALUES ('268fe17d-e3be-4fb7-b93f-1aabb6ac4737', 'ASU-001', 'ASUS Vivobook 15 X1504VA i5-1335U/16GB/512GB/15.6\" FHD', 'ASUS', '14990000.00', '16490000.00', '22', '23594534-c6e5-4f0c-863c-988a366134a9', 'Intel Core i5-1335U (10 nhân 12 luồng, tối đa 4.6GHz)', '16GB DDR4 3200MHz (8GB onboard + 8GB)', '16', '512GB SSD M.2 PCIe NVMe', '512', 'Intel Iris Xe Graphics', '15.6 inch Full HD (1920 x 1080), IPS, 60Hz, chống chói', '3 cell 42Wh', '1.70 kg', 'Windows 11 Home bản quyền', '1 x USB-C 3.2, 2 x USB-A 3.2, 1 x USB 2.0, 1 x HDMI 1.4, 1 x jack 3.5mm', 'Wi-Fi 6E, Bluetooth 5.3', 'Xanh (Quiet Blue)', '24', '1', 'ASUS Vivobook 15 là chiếc laptop học tập – văn phòng bán chạy hàng đầu nhờ cấu hình 16GB RAM ngay từ đầu, bản lề mở phẳng 180 độ và tấm che webcam vật lý bảo vệ quyền riêng tư. Bảo hành 2 năm chính hãng.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Intel Core i5-1335U (10 nhân 12 luồng, tối đa 4.6GHz), đi kèm 16GB DDR4 3200MHz (8GB onboard + 8GB) và ổ cứng 512GB SSD M.2 PCIe NVMe. Máy đáp ứng trơn tru các tác vụ Word, Excel, PowerPoint, họp trực tuyến, học online và mở nhiều tab trình duyệt cùng lúc.\n\n## Card đồ họa\n\nIntel Iris Xe Graphics. Đồ họa tích hợp đủ để xem phim 4K, chỉnh sửa ảnh cơ bản và chơi các game nhẹ.\n\n## Màn hình\n\n15.6 inch Full HD (1920 x 1080), IPS, 60Hz, chống chói. Tấm nền IPS góc nhìn rộng kết hợp lớp phủ chống chói giúp làm việc lâu dưới đèn văn phòng hay ngoài trời vẫn dễ chịu.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 1.70 kg, màu Xanh (Quiet Blue). Pin 3 cell 42Wh, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành Windows 11 Home bản quyền được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n1 x USB-C 3.2, 2 x USB-A 3.2, 1 x USB 2.0, 1 x HDMI 1.4, 1 x jack 3.5mm. Kết nối không dây: Wi-Fi 6E, Bluetooth 5.3.\n\n## Phù hợp với\n\nHọc sinh, sinh viên, nhân viên văn phòng, giáo viên và gia đình cần một chiếc máy bền bỉ, dễ dùng với chi phí hợp lý.\n\n## Cam kết tại LAPSTORE\n\nSản phẩm chín