INSERT INTO product VALUES ('43682163-2378-4b04-9fbe-0443ced90be9', 'MSI-005', 'MSI Cyborg 15 A12VE i5-12450H/16GB/512GB/RTX 4050/15.6\" 144Hz', 'MSI', '21990000.00', '24990000.00', '13', 'bcbc7029-3eec-4097-a7cb-233ad485346e', 'Intel Core i5-12450H (8 nhân 12 luồng, tối đa 4.4GHz)', '16GB DDR5 4800MHz (2 x 8GB)', '16', '512GB SSD M.2 PCIe NVMe', '512', 'NVIDIA GeForce RTX 4050 6GB GDDR6', '15.6 inch Full HD (1920 x 1080), IPS, 144Hz', '3 cell 53.5Wh', '1.98 kg', 'Windows 11 Home bản quyền', '1 x USB-C 3.2, 2 x USB-A 3.2, 1 x HDMI 2.1, 1 x RJ45 LAN, 1 x jack 3.5mm', 'Wi-Fi 6, Bluetooth 5.3', 'Đen trong suốt (Translucent Black)', '24', '0', 'MSI Cyborg 15 có thiết kế lấy cảm hứng từ cyberpunk với các chi tiết nhựa trong suốt để lộ linh kiện bên trong cực kỳ độc đáo. Trọng lượng dưới 2kg rất hiếm cho một laptop RTX 4050.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Intel Core i5-12450H (8 nhân 12 luồng, tối đa 4.4GHz), đi kèm 16GB DDR5 4800MHz (2 x 8GB) và ổ cứng 512GB SSD M.2 PCIe NVMe. Cấu hình này đủ sức chiến mượt các tựa game AAA lẫn eSports, đồng thời xử lý tốt livestream, dựng video và các tác vụ nặng khác.\n\n## Card đồ họa\n\nNVIDIA GeForce RTX 4050 6GB GDDR6. Card hỗ trợ công nghệ DLSS và Ray Tracing, tăng tốc khung hình khi chơi game và rút ngắn thời gian render, xuất video.\n\n## Màn hình\n\n15.6 inch Full HD (1920 x 1080), IPS, 144Hz. Tần số quét cao giúp mọi chuyển động mượt mà, mang lại lợi thế lớn trong các game bắn súng và đua xe tốc độ cao.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 1.98 kg, màu Đen trong suốt (Translucent Black). Pin 3 cell 53.5Wh, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành Windows 11 Home bản quyền được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n1 x USB-C 3.2, 2 x USB-A 3.2, 1 x HDMI 2.1, 1 x RJ45 LAN, 1 x jack 3.5mm. Kết nối không dây: Wi-Fi 6, Bluetooth 5.3.\n\n## Phù hợp với\n\nGame thủ, streamer, sinh viên công nghệ thông tin và những ai cần một cỗ máy hiệu năng cao cho cả giải trí lẫn công việc nặng.\n\n## Cam kết tại LAPSTORE\n\nSản phẩm chính hãng mới 100%, nguyên seal. Bảo hành 24 tháng theo tiêu chuẩn nhà sản xuất, 1 đổi 1 trong 15 ngày nếu có lỗi phần cứng. Miễn phí giao hàng toàn quốc, hỗ trợ cài đặt phần mềm trọn đời và trả góp 0% qua thẻ tín dụng.', '/images/products/msi-005.jpg', '2026-10-24 21:19:13.315', '2026-10-24 21:19:13.315', '0');
INSERT INTO product VALUES ('4aede354-a928-49c1-8580-821b4820c546', 'APL-007', 'MacBook Pro 14 inch M4 Pro 2024 24GB/512GB', 'Apple', '49990000.00', '52990000.00', '7', 'a58c12cd-1d1a-4194-b99a-080c011a7638', 'Apple M4 Pro (12 nhân CPU: 8 hiệu năng + 4 tiết kiệm điện)', '24GB bộ nhớ hợp nhất', '24', '512GB SSD', '512', 'GPU 16 nhân, băng thông bộ nhớ 273GB/s', '14.2 inch Liquid Retina XDR (3024 x 1964), ProMotion 120Hz, tùy chọn lớp phủ Nano-texture', '72.4Wh, tới 22 giờ xem video', '1.60 kg', 'macOS Sequoia', '3 x Thunderbolt 5, 1 x HDMI (8K), 1 x khe thẻ SDXC, 1 x MagSafe 3, 1 x jack tai nghe 3.5mm', 'Wi-Fi 6E, Bluetooth 5.3', 'Bạc (Silver)', '12', '0', 'Với chip M4 Pro và cổng Thunderbolt 5 thế hệ mới, MacBook Pro 14 inch này xử lý mượt mà timeline 4K nhiều lớp trong Final Cut Pro, biên dịch dự án lớn trong Xcode và chạy mô hình AI cục bộ một cách nhanh chóng.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Apple M4 Pro (12 nhân CPU: 8 hiệu năng + 4 tiết kiệm điện), đi kèm 24GB bộ nhớ hợp nhất và ổ cứng 512GB SSD. Hiệu năng mạnh mẽ giúp xử lý mượt các phần mềm Photoshop, Illustrator, Premiere Pro, AutoCAD, Blender và các dự án nhiều lớp.\n\n## Card đồ họa\n\nGPU 16 nhân, băng thông bộ nhớ 273GB/s. GPU tích hợp trên chip Apple Silicon được tối ưu cho Final Cut Pro, Lightroom, Xcode và hàng nghìn ứng dụng trên macOS.\n\n## Màn hình\n\n14.2 inch Liquid Retina XDR (3024 x 1964), ProMotion 120Hz, tùy chọn lớp phủ Nano-texture. Công nghệ đèn nền Mini-LED cho độ sáng HDR rất cao, chi tiết vùng tối – vùng sáng rõ ràng, đáp ứng công việc màu sắc chuyên nghiệp.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 1.60 kg, màu Bạc (Silver). Pin 72.4Wh, tới 22 giờ xem video, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành macOS Sequoia được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n3 x Thunderbolt 5, 1 x HDMI (8K), 1 x khe thẻ SDXC, 1 x MagSafe 3, 1 x jack tai nghe 3.5mm. Kết nối không dây: Wi-Fi 6E, Bluetooth 5.3.\n\n## Phù hợp với\n\nNhà thiết kế đồ họa, kiến trúc sư, kỹ sư, nhiếp ảnh gia, người dựng phim và lập trình viên cần hiệu năng xử lý chuyên sâu.\n\n## Cam kết tại LAPSTORE\n\nSản phẩm chính hãng mới 100%, nguyên seal. Bảo hành 12 tháng theo tiêu chuẩn nhà sản xuất, 1 đổi 1 trong 15 ngày nếu có lỗi phần cứng. Miễn phí giao hàng toàn quốc, hỗ trợ cài đặt phần mềm trọn đời và trả góp 0% qua thẻ tín dụng.', '/images/products/apl-007.jpg', '2026-10-24 21:19:12.744', '2026-10-24 21:19:12.744', '0');
