INSERT INTO product VALUES ('5f5afbaf-54ee-4f39-987c-654e08c2247d', 'ASU-006', 'ASUS TUF Gaming F15 FX507ZC4 i5-12500H/8GB/512GB/RTX 3050/15.6\" 144Hz', 'ASUS', '18990000.00', '21990000.00', '19', 'bcbc7029-3eec-4097-a7cb-233ad485346e', 'Intel Core i5-12500H (12 nhân 16 luồng, tối đa 4.5GHz)', '8GB DDR4 3200MHz (2 khe, tối đa 32GB)', '8', '512GB SSD M.2 PCIe NVMe', '512', 'NVIDIA GeForce RTX 3050 4GB GDDR6', '15.6 inch Full HD (1920 x 1080), IPS, 144Hz, Adaptive-Sync', '3 cell 56Wh', '2.20 kg', 'Windows 11 Home bản quyền', '1 x Thunderbolt 4, 2 x USB-A 3.2, 1 x HDMI 2.0b, 1 x RJ45 LAN, 1 x jack 3.5mm', 'Wi-Fi 6, Bluetooth 5.2', 'Xám (Mecha Gray)', '24', '0', 'TUF Gaming F15 là laptop gaming \'nhập môn\' được game thủ Việt tin dùng nhờ độ bền chuẩn quân đội, bàn phím đèn nền RGB và khả năng chiến mượt các tựa game eSports như Valorant, CS2, Liên Minh Huyền Thoại ở mức FPS cao.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Intel Core i5-12500H (12 nhân 16 luồng, tối đa 4.5GHz), đi kèm 8GB DDR4 3200MHz (2 khe, tối đa 32GB) và ổ cứng 512GB SSD M.2 PCIe NVMe. Cấu hình này đủ sức chiến mượt các tựa game AAA lẫn eSports, đồng thời xử lý tốt livestream, dựng video và các tác vụ nặng khác.\n\n## Card đồ họa\n\nNVIDIA GeForce RTX 3050 4GB GDDR6. Card hỗ trợ công nghệ DLSS và Ray Tracing, tăng tốc khung hình khi chơi game và rút ngắn thời gian render, xuất video.\n\n## Màn hình\n\n15.6 inch Full HD (1920 x 1080), IPS, 144Hz, Adaptive-Sync. Tần số quét cao giúp mọi chuyển động mượt mà, mang lại lợi thế lớn trong các game bắn súng và đua xe tốc độ cao.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 2.20 kg, màu Xám (Mecha Gray). Pin 3 cell 56Wh, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành Windows 11 Home bản quyền được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n1 x Thunderbolt 4, 2 x USB-A 3.2, 1 x HDMI 2.0b, 1 x RJ45 LAN, 1 x jack 3.5mm. Kết nối không dây: Wi-Fi 6, Bluetooth 5.2.\n\n## Phù hợp với\n\nGame thủ, streamer, sinh viên công nghệ thông tin và những ai cần một cỗ máy hiệu năng cao cho cả giải trí lẫn công việc nặng.\n\n## Cam kết tại LAPSTORE\n\nSản phẩm chính hãng mới 100%, nguyên seal. Bảo hành 24 tháng theo tiêu chuẩn nhà sản xuất, 1 đổi 1 trong 15 ngày nếu có lỗi phần cứng. Miễn phí giao hàng toàn quốc, hỗ trợ cài đặt phần mềm trọn đời và trả góp 0% qua thẻ tín dụng.', '/images/products/asu-006.jpg', '2026-10-24 21:19:12.923', '2026-10-24 21:19:12.923', '0');
INSERT INTO product VALUES ('60bb5bd0-d7b2-4bce-a2c3-7d698883b1e0', 'APL-008', 'MacBook Pro 16 inch M4 Pro 2024 24GB/512GB', 'Apple', '62990000.00', '64990000.00', '5', 'a58c12cd-1d1a-4194-b99a-080c011a7638', 'Apple M4 Pro (14 nhân CPU)', '24GB bộ nhớ hợp nhất', '24', '512GB SSD', '512', 'GPU 20 nhân tích hợp', '16.2 inch Liquid Retina XDR (3456 x 2234), ProMotion 120Hz, 1000 nits (HDR 1600 nits)', '100Wh, tới 24 giờ xem video', '2.14 kg', 'macOS Sequoia', '3 x Thunderbolt 5, 1 x HDMI, 1 x khe thẻ SDXC, 1 x MagSafe 3, 1 x jack tai nghe 3.5mm', 'Wi-Fi 6E, Bluetooth 5.3', 'Space Black', '12', '0', 'MacBook Pro 16 inch sở hữu màn hình lớn nhất dòng Mac laptop và viên pin 100Wh – mức tối đa được phép mang lên máy bay. Hệ thống 6 loa hỗ trợ âm thanh không gian giúp máy trở thành một studio di động đúng nghĩa.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Apple M4 Pro (14 nhân CPU), đi kèm 24GB bộ nhớ hợp nhất và ổ cứng 512GB SSD. Hiệu năng mạnh mẽ giúp xử lý mượt các phần mềm Photoshop, Illustrator, Premiere Pro, AutoCAD, Blender và các dự án nhiều lớp.\n\n## Card đồ họa\n\nGPU 20 nhân tích hợp. GPU tích hợp trên chip Apple Silicon được tối ưu cho Final Cut Pro, Lightroom, Xcode và hàng nghìn ứng dụng trên macOS.\n\n## Màn hình\n\n16.2 inch Liquid Retina XDR (3456 x 2234), ProMotion 120Hz, 1000 nits (HDR 1600 nits). Công nghệ đèn nền Mini-LED cho độ sáng HDR rất cao, chi tiết vùng tối – vùng sáng rõ ràng, đáp ứng công việc màu sắc chuyên nghiệp.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 2.14 kg, màu Space Black. Pin 100Wh, tới 24 giờ xem video, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành macOS Sequoia được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n3 x Thunderbolt 5, 1 x HDMI, 1 x khe thẻ SDXC, 1 x MagSafe 3, 1 x jack tai nghe 3.5mm. Kết nối không dây: Wi-Fi 6E, Bluetooth 5.3.\n\n## Phù hợp với\n\nNhà thiết kế đồ họa, kiến trúc sư, kỹ sư, nhiếp ảnh gia, người dựng phim và lập trình viên cần hiệu năng xử lý chuyên sâu.\n\n## Cam kết tại LAPSTORE\n\nSản phẩm chính hãng mới 100%, nguyên seal. Bảo hành 12 tháng theo tiêu chuẩn nhà sản xuất, 1 đổi 1 trong 15 ngày nếu có lỗi phần cứng. Miễn phí giao hàng toàn quốc, hỗ trợ cài đặt phần mềm trọn đời và trả góp 0% qua thẻ tín dụng.', '/images/products/apl-008.jpg', '2026-10-24 21:19:12.754', '2026-10-24 21:19:12.754', '0');
