INSERT INTO product VALUES ('66c47182-6fb3-4f4e-9417-35f5be48e6f9', 'ACR-004', 'Acer TravelMate P2 TMP214-55 i5-1335U/16GB/512GB/14\" FHD', 'Acer', '17490000.00', null, '8', 'a57061a1-da3d-4f06-b8bf-a802d13f355a', 'Intel Core i5-1335U (10 nhân 12 luồng, tối đa 4.6GHz)', '16GB DDR4 3200MHz (2 khe, tối đa 32GB)', '16', '512GB SSD M.2 PCIe NVMe', '512', 'Intel Iris Xe Graphics', '14 inch Full HD (1920 x 1080), IPS, chống chói', '3 cell 50Wh', '1.50 kg', 'Windows 11 Home bản quyền', '1 x Thunderbolt 4, 1 x USB-C 3.2, 2 x USB-A 3.2, 1 x HDMI 2.0, 1 x RJ45 LAN, 1 x đầu đọc thẻ microSD, 1 x jack 3.5mm', 'Wi-Fi 6E, Bluetooth 5.2', 'Đen (Shale Black)', '24', '0', 'Acer TravelMate P2 là laptop doanh nghiệp đạt chuẩn quân đội MIL-STD 810H, có cảm biến vân tay và chip bảo mật TPM 2.0. Bàn phím chống tràn và đầy đủ cổng kết nối giúp máy làm việc bền bỉ tại văn phòng lẫn công tác.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Intel Core i5-1335U (10 nhân 12 luồng, tối đa 4.6GHz), đi kèm 16GB DDR4 3200MHz (2 khe, tối đa 32GB) và ổ cứng 512GB SSD M.2 PCIe NVMe. Máy vận hành ổn định, bảo mật cao, chạy tốt các ứng dụng doanh nghiệp như ERP, CRM, phần mềm kế toán và họp trực tuyến cả ngày.\n\n## Card đồ họa\n\nIntel Iris Xe Graphics. Đồ họa tích hợp đủ để xem phim 4K, chỉnh sửa ảnh cơ bản và chơi các game nhẹ.\n\n## Màn hình\n\n14 inch Full HD (1920 x 1080), IPS, chống chói. Tấm nền IPS góc nhìn rộng kết hợp lớp phủ chống chói giúp làm việc lâu dưới đèn văn phòng hay ngoài trời vẫn dễ chịu.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 1.50 kg, màu Đen (Shale Black). Pin 3 cell 50Wh, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành Windows 11 Home bản quyền được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n1 x Thunderbolt 4, 1 x USB-C 3.2, 2 x USB-A 3.2, 1 x HDMI 2.0, 1 x RJ45 LAN, 1 x đầu đọc thẻ microSD, 1 x jack 3.5mm. Kết nối không dây: Wi-Fi 6E, Bluetooth 5.2.\n\n## Phù hợp với\n\nDoanh nhân, quản lý, nhân viên doanh nghiệp cần một chiếc máy chuyên nghiệp, bảo mật và được hỗ trợ bảo hành dài hạn.\n\n## Cam kết tại LAPSTORE\n\nSản phẩm chính hãng mới 100%, nguyên seal. Bảo hành 24 tháng theo tiêu chuẩn nhà sản xuất, 1 đổi 1 trong 15 ngày nếu có lỗi phần cứng. Miễn phí giao hàng toàn quốc, hỗ trợ cài đặt phần mềm trọn đời và trả góp 0% qua thẻ tín dụng.', '/images/products/acr-004.jpg', '2026-10-24 21:19:13.189', '2026-10-24 21:19:13.189', '0');
INSERT INTO product VALUES ('68993640-f85f-4690-8bc8-6e57c6bc8831', 'DEL-006', 'Dell XPS 13 9340 Core Ultra 7 155H/16GB/512GB/13.4\" FHD+ 120Hz', 'Dell', '39990000.00', '44990000.00', '6', '54ee350b-95fb-436d-a6ec-b333bb394258', 'Intel Core Ultra 7 155H (16 nhân 22 luồng, tối đa 4.8GHz, tích hợp NPU AI)', '16GB LPDDR5x 7467MHz', '16', '512GB SSD M.2 PCIe Gen4 NVMe', '512', 'Intel Arc Graphics', '13.4 inch FHD+ (1920 x 1200), 120Hz, 500 nits, InfinityEdge', '3 cell 55Wh', '1.19 kg', 'Windows 11 Home bản quyền', '2 x Thunderbolt 4 (USB-C), kèm đầu chuyển USB-C sang USB-A', 'Wi-Fi 7, Bluetooth 5.4', 'Bạc (Platinum)', '12', '1', 'Dell XPS 13 9340 là biểu tượng của laptop Windows cao cấp: hàng phím chức năng cảm ứng, touchpad liền mạch không viền và khung máy nhôm CNC nguyên khối. Thiết kế tối giản tuyệt đối dành cho người yêu cái đẹp.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Intel Core Ultra 7 155H (16 nhân 22 luồng, tối đa 4.8GHz, tích hợp NPU AI), đi kèm 16GB LPDDR5x 7467MHz và ổ cứng 512GB SSD M.2 PCIe Gen4 NVMe. Cấu hình cân bằng giữa hiệu năng và thời lượng pin: khởi động nhanh, vận hành mát và êm, đủ mạnh cho công việc văn phòng lẫn sáng tạo nhẹ.\n\n## Card đồ họa\n\nIntel Arc Graphics. Đồ họa tích hợp đủ để xem phim 4K, chỉnh sửa ảnh cơ bản và chơi các game nhẹ.\n\n## Màn hình\n\n13.4 inch FHD+ (1920 x 1200), 120Hz, 500 nits, InfinityEdge. Tấm nền IPS góc nhìn rộng kết hợp lớp phủ chống chói giúp làm việc lâu dưới đèn văn phòng hay ngoài trời vẫn dễ chịu.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 1.19 kg, màu Bạc (Platinum). Pin 3 cell 55Wh, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành Windows 11 Home bản quyền được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n2 x Thunderbolt 4 (USB-C), kèm đầu chuyển USB-C sang USB-A. Kết nối không dây: Wi-Fi 7, Bluetooth 5.4.\n\n## Phù hợp với\n\nNgười thường xuyên di chuyển, làm việc tại quán cà phê, sinh viên và dân văn phòng yêu thích sự gọn nhẹ, thời trang.\n\n## Cam kết tại LAPSTORE\n\