INSERT INTO product VALUES ('6dfb5bf8-c3cc-4eda-9c5e-495a077aa6f2', 'APL-009', 'MacBook Pro 14 inch M4 Max 2024 36GB/1TB', 'Apple', '79990000.00', '83990000.00', '3', 'a58c12cd-1d1a-4194-b99a-080c011a7638', 'Apple M4 Max (14 nhân CPU: 10 hiệu năng + 4 tiết kiệm điện)', '36GB bộ nhớ hợp nhất', '36', '1TB SSD', '1024', 'GPU 32 nhân, băng thông bộ nhớ 410GB/s', '14.2 inch Liquid Retina XDR (3024 x 1964), ProMotion 120Hz, 1000 nits (HDR 1600 nits)', '72.4Wh, tới 18 giờ xem video', '1.62 kg', 'macOS Sequoia', '3 x Thunderbolt 5, 1 x HDMI (8K), 1 x khe thẻ SDXC, 1 x MagSafe 3, 1 x jack tai nghe 3.5mm', 'Wi-Fi 6E, Bluetooth 5.3', 'Space Black', '12', '0', 'M4 Max biến chiếc MacBook Pro 14 inch nhỏ gọn thành cỗ máy trạm thực thụ: dựng phim 8K ProRes, render 3D trong Blender hay huấn luyện mô hình máy học đều được xử lý ngay trên máy với tốc độ ấn tượng.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Apple M4 Max (14 nhân CPU: 10 hiệu năng + 4 tiết kiệm điện), đi kèm 36GB bộ nhớ hợp nhất và ổ cứng 1TB SSD. Hiệu năng mạnh mẽ giúp xử lý mượt các phần mềm Photoshop, Illustrator, Premiere Pro, AutoCAD, Blender và các dự án nhiều lớp.\n\n## Card đồ họa\n\nGPU 32 nhân, băng thông bộ nhớ 410GB/s. GPU tích hợp trên chip Apple Silicon được tối ưu cho Final Cut Pro, Lightroom, Xcode và hàng nghìn ứng dụng trên macOS.\n\n## Màn hình\n\n14.2 inch Liquid Retina XDR (3024 x 1964), ProMotion 120Hz, 1000 nits (HDR 1600 nits). Công nghệ đèn nền Mini-LED cho độ sáng HDR rất cao, chi tiết vùng tối – vùng sáng rõ ràng, đáp ứng công việc màu sắc chuyên nghiệp.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 1.62 kg, màu Space Black. Pin 72.4Wh, tới 18 giờ xem video, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành macOS Sequoia được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n3 x Thunderbolt 5, 1 x HDMI (8K), 1 x khe thẻ SDXC, 1 x MagSafe 3, 1 x jack tai nghe 3.5mm. Kết nối không dây: Wi-Fi 6E, Bluetooth 5.3.\n\n## Phù hợp với\n\nNhà thiết kế đồ họa, kiến trúc sư, kỹ sư, nhiếp ảnh gia, người dựng phim và lập trình viên cần hiệu năng xử lý chuyên sâu.\n\n## Cam kết tại LAPSTORE\n\nSản phẩm chính hãng mới 100%, nguyên seal. Bảo hành 12 tháng theo tiêu chuẩn nhà sản xuất, 1 đổi 1 trong 15 ngày nếu có lỗi phần cứng. Miễn phí giao hàng toàn quốc, hỗ trợ cài đặt phần mềm trọn đời và trả góp 0% qua thẻ tín dụng.', '/images/products/apl-009.jpg', '2026-10-24 21:19:12.762', '2026-10-24 21:19:12.762', '0');
