INSERT INTO product VALUES ('a3f2d16a-ca3c-44d0-82de-ef783fb69988', 'APL-004', 'MacBook Air 15 inch M3 2024 8GB/256GB', 'Apple', '27490000.00', '32990000.00', '5', '54ee350b-95fb-436d-a6ec-b333bb394258', 'Apple M3 (8 nhân CPU)', '8GB bộ nhớ hợp nhất', '8', '256GB SSD', '256', 'GPU 10 nhân tích hợp', '15.3 inch Liquid Retina (2880 x 1864), 500 nits, dải màu P3', '66.5Wh, tới 18 giờ xem video', '1.51 kg', 'macOS Sequoia', '2 x Thunderbolt / USB 4, 1 x MagSafe 3, 1 x jack tai nghe 3.5mm', 'Wi-Fi 6E, Bluetooth 5.3', 'Space Gray', '12', '0', 'MacBook Air 15 inch mang đến không gian hiển thị rộng rãi trong một thân máy chỉ dày 11.5mm. Hệ thống 6 loa với Force-cancelling woofers cho âm thanh lớn, trầm ấm – điều hiếm thấy trên một chiếc laptop mỏng nhẹ.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Apple M3 (8 nhân CPU), đi kèm 8GB bộ nhớ hợp nhất và ổ cứng 256GB SSD. Cấu hình cân bằng giữa hiệu năng và thời lượng pin: khởi động nhanh, vận hành mát và êm, đủ mạnh cho công việc văn phòng lẫn sáng tạo nhẹ.\n\n## Card đồ họa\n\nGPU 10 nhân tích hợp. GPU tích hợp trên chip Apple Silicon được tối ưu cho Final Cut Pro, Lightroom, Xcode và hàng nghìn ứng dụng trên macOS.\n\n## Màn hình\n\n15.3 inch Liquid Retina (2880 x 1864), 500 nits, dải màu P3. Độ phân giải cao cho chữ hiển thị sắc nét, màu sắc chính xác, đọc tài liệu cả ngày không mỏi mắt.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 1.51 kg, màu Space Gray. Pin 66.5Wh, tới 18 giờ xem video, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành macOS Sequoia được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n2 x Thunderbolt / USB 4, 1 x MagSafe 3, 1 x jack tai nghe 3.5mm. Kết nối không dây: Wi-Fi 6E, Bluetooth 5.3.\n\n## Phù hợp với\n\nNgười thường xuyên di chuyển, làm việc tại quán cà phê, sinh viên và dân văn phòng yêu thích sự gọn nhẹ, thời trang.\n\n## Cam kết tại LAPSTORE\n\nSản phẩm chính hãng mới 100%, nguyên seal. Bảo hành 12 tháng theo tiêu chuẩn nhà sản xuất, 1 đổi 1 trong 15 ngày nếu có lỗi phần