INSERT INTO product VALUES ('bcb2b71e-a848-4d15-a931-cc0718651708', 'APL-001', 'MacBook Air 13 inch M2 2022 8GB/256GB', 'Apple', '18990000.00', '24990000.00', '15', '54ee350b-95fb-436d-a6ec-b333bb394258', 'Apple M2 (8 nhân CPU: 4 hiệu năng + 4 tiết kiệm điện)', '8GB bộ nhớ hợp nhất', '8', '256GB SSD', '256', 'GPU 8 nhân tích hợp trên chip M2', '13.6 inch Liquid Retina (2560 x 1664), 500 nits, dải màu P3, True Tone', '52.6Wh, tới 18 giờ xem video', '1.24 kg', 'macOS Sequoia', '2 x Thunderbolt / USB 4, 1 x MagSafe 3, 1 x jack tai nghe 3.5mm', 'Wi-Fi 6 (802.11ax), Bluetooth 5.3', 'Midnight', '12', '1', 'MacBook Air M2 là lựa chọn \'quốc dân\' cho sinh viên và dân văn phòng muốn bước vào hệ sinh thái Apple với mức giá dễ tiếp cận. Thiết kế phẳng vuông vức, viền màn hình mỏng cùng tai thỏ chứa webcam 1080p mang lại diện mạo hiện đại không kém các thế hệ mới.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Apple M2 (8 nhân CPU: 4 hiệu năng + 4 tiết kiệm điện), đi kèm 8GB bộ nhớ hợp nhất và ổ cứng 256GB SSD. Cấu hình cân bằng giữa hiệu năng và thời lượng pin: khởi động nhanh, vận hành mát và êm, đủ mạnh cho công việc văn phòng lẫn sáng tạo nhẹ.\n\n## Card đồ họa\n\nGPU 8 nhân tích hợp trên chip M2. GPU tích hợp trên chip Apple Silicon được tối ưu cho Final Cut Pro, Lightroom, Xcode và hàng nghìn ứng dụng trên macOS.\n\n## Màn hình\n\n13.6 inch Liquid Retina (2560 x 1664), 500 nits, dải màu P3, True Tone. Độ phân giải cao cho chữ hiển thị sắc nét, màu sắc chính xác, đọc tài liệu cả ngày không mỏi mắt.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 1.24 kg, màu Midnight. Pin 52.6Wh, tới 18 giờ xem video, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành macOS Sequoia được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n2 x Thunderbolt / USB 4, 1 x MagSafe 3, 1 x jack tai nghe 3.5mm. Kết nối không dây: Wi-Fi 6 (802.11ax), Bluetooth 5.3.\n\n## Phù hợp với\n\nNgười thường xuyên di chuyển, làm việc tại quán cà phê, sinh viên và dân văn phòng yêu thích sự gọn nh