INSERT INTO product VALUES ('c407e55b-5677-44ba-a5f4-4aaf670fa63e', 'ACR-010', 'Acer Predator Helios 16 PH16-72 i9-14900HX/32GB/1TB/RTX 4080/16\" 240Hz', 'Acer', '72990000.00', '79990000.00', '2', 'bcbc7029-3eec-4097-a7cb-233ad485346e', 'Intel Core i9-14900HX (24 nhân 32 luồng, tối đa 5.8GHz)', '32GB DDR5 5600MHz', '32', '1TB SSD M.2 PCIe Gen4 NVMe', '1024', 'NVIDIA GeForce RTX 4080 12GB GDDR6, TGP 175W', '16 inch WQXGA (2560 x 1600), Mini-LED, 240Hz, 1000 nits, 100% DCI-P3', '4 cell 90Wh', '2.70 kg', 'Windows 11 Home bản quyền', '2 x Thunderbolt 4, 3 x USB-A 3.2, 1 x HDMI 2.1, 1 x RJ45 LAN 2.5G, 1 x đầu đọc thẻ microSD, 1 x jack 3.5mm', 'Wi-Fi 7, Bluetooth 5.4', 'Đen (Abyssal Black)', '24', '0', 'Predator Helios 16 là quái vật gaming với màn hình Mini-LED 1000 nits, i9-14900HX và RTX 4080. Bàn phím Mini-LED RGB từng phím, nắp lưng có dải đèn trong suốt tạo nên vẻ ngoài đầy uy lực.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Intel Core i9-14900HX (24 nhân 32 luồng, tối đa 5.8GHz), đi kèm 32GB DDR5 5600MHz và ổ cứng 1TB SSD M.2 PCIe Gen4 NVMe. Cấu hình này đủ sức chiến mượt các tựa game AAA lẫn eSports, đồng thời xử lý tốt livestream, dựng video và các tác vụ nặng khác.\n\n## Card đồ họa\n\nNVIDIA GeForce RTX 4080 12GB GDDR6, TGP 175W. Card hỗ trợ công nghệ DLSS và Ray Tracing, tăng tốc khung hình khi chơi game và rút ngắn thời gian render, xuất video.\n\n## Màn hình\n\n16 inch WQXGA (2560 x 1600), Mini-LED, 240Hz, 1000 nits, 100% DCI-P3. Công nghệ đèn nền Mini-LED cho độ sáng HDR rất cao, chi tiết vùng tối – vùng sáng rõ ràng, đáp ứng công việc màu sắc chuyên nghiệp.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 2.70 kg, màu Đen (Abyssal Black). Pin 4 cell 90Wh, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành Windows 11 Home bản quyền được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n2 x Thunderbolt 4, 3 x USB-A 3.2, 1 x HDMI 2.1, 1 x RJ45 LAN 2.5G, 1 x đầu đọc thẻ microSD, 1 x jack 3.5mm. Kết nối không dây: Wi-Fi 7, Bluetooth 5.4.\n\n## Phù hợp với\n\nGame thủ, streamer, sinh viên công nghệ thông tin và những ai cần một cỗ máy hiệu năng cao cho cả giải trí lẫn công việc nặng.\n\n## Cam kết tại LAPSTORE\n\nSản phẩm chính hãng mới 100%, nguyên seal. Bảo hành 24 tháng theo tiêu chuẩn nhà sản xuất, 1 đổi 1 trong 15 ngày nếu có lỗi phần cứng. Miễn phí giao hàng toàn quốc, hỗ trợ cài đặt phần mềm trọn đời và trả góp 0% qua thẻ tín dụng.', '/images/products/acr-010.jpg', '2026-10-24 21:19:13.236', '2026-10-24 21:19:13.236', '0');
