INSERT INTO product VALUES ('d3f289c8-e670-4952-bf75-a918a24400f5', 'APL-002', 'MacBook Air 13 inch M3 2024 16GB/256GB', 'Apple', '24490000.00', '27990000.00', '12', '54ee350b-95fb-436d-a6ec-b333bb394258', 'Apple M3 (8 nhân CPU)', '16GB bộ nhớ hợp nhất', '16', '256GB SSD', '256', 'GPU 10 nhân, hỗ trợ dò tia (ray tracing) phần cứng', '13.6 inch Liquid Retina (2560 x 1664), 500 nits, dải màu P3', '52.6Wh, tới 18 giờ xem video', '1.24 kg', 'macOS Sequoia', '2 x Thunderbolt / USB 4, 1 x MagSafe 3, 1 x jack tai nghe 3.5mm', 'Wi-Fi 6E, Bluetooth 5.3', 'Starlight', '12', '0', 'MacBook Air M3 kế thừa thiết kế mỏng nhẹ không quạt tản nhiệt, hoạt động hoàn toàn yên tĩnh nhưng mạnh hơn rõ rệt so với thế hệ trước. Phiên bản 16GB RAM giúp máy đa nhiệm thoải mái và sẵn sàng cho các tính năng Apple Intelligence.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Apple M3 (8 nhân CPU), đi kèm 16GB bộ nhớ hợp nhất và ổ cứng 256GB SSD. Cấu hình cân bằng giữa hiệu năng và thời lượng pin: khởi động nhanh, vận hành mát và êm, đủ mạnh cho công việc văn phòng lẫn sáng tạo nhẹ.\n\n## Card đồ họa\n\nGPU 10 nhân, hỗ trợ dò tia (ray tracing) phần cứng. GPU tích hợp trên chip Apple Silicon được tối ưu cho Final Cut Pro, Lightroom, Xcode và hàng nghìn ứng dụng trên macOS.\n\n## Màn hình\n\n13.6 inch Liquid Retina (2560 x 1664), 500 nits, dải màu P3. Độ phân giải cao cho chữ hiển thị sắc nét, màu sắc chính xác, đọc tài liệu cả ngày không mỏi mắt.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 1.24 kg, màu Starlight. Pin 52.6Wh, tới 18 giờ xem video, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành macOS Sequoia được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n2 x Thunderbolt / USB 4, 1 x MagSafe 3, 1 x jack tai nghe 3.5mm. Kết nối không dây: Wi-Fi 6E, Bluetooth 5.3.\n\n## Phù hợp với\n\nNgười thường xuyên di chuyển, làm việc tại quán cà phê, sinh viên và dân văn phòng yêu thích sự gọn nhẹ, thời trang.\n\n## Cam kết tại LAPSTORE\n\nSản phẩm chính hãng mới 100%, nguyên seal. Bảo hành 12 tháng theo tiêu chuẩn nhà sản xuất, 1 đổi 1 trong 15 ngày nếu có lỗi phần cứng. Miễn phí giao hàng toàn quốc, hỗ trợ cài đặt phần mềm trọn đời và trả góp 0% qua thẻ tín dụng.', '/images/products/apl-002.jpg', '2026-10-24 21:19:12.686', '2026-10-24 21:19:12.686', '0');
INSERT INTO product VALUES ('d43fbfdb-0e90-4c28-85d5-f5c5d37fc897', 'MSI-001', 'MSI Modern 14 C13M i5-1335U/16GB/512GB/14\" FHD', 'MSI', '13490000.00', '14990000.00', '19', '23594534-c6e5-4f0c-863c-988a366134a9', 'Intel Core i5-1335U (10 nhân 12 luồng, tối đa 4.6GHz)', '16GB DDR4 3200MHz (1 khe, tối đa 64GB)', '16', '512GB SSD M.2 PCIe NVMe', '512', 'Intel Iris Xe Graphics', '14 inch Full HD (1920 x 1080), IPS, 60Hz, chống chói', '3 cell 39.3Wh', '1.40 kg', 'Windows 11 Home bản quyền', '1 x USB-C 3.2, 2 x USB-A 3.2, 1 x HDMI 1.4, 1 x đầu đọc thẻ microSD, 1 x jack 3.5mm', 'Wi-Fi 6E, Bluetooth 5.3', 'Hồng (Beige Rose)', '24', '1', 'MSI Modern 14 là laptop văn phòng gọn nhẹ với bản lề mở 180 độ, bàn phím có đèn nền và trọng lượng chỉ 1.4kg. 16GB RAM giúp máy đáp ứng tốt nhu cầu học tập, làm việc đa nhiệm trong tầm giá dưới 14 triệu.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Intel Core i5-1335U (10 nhân 12 luồng, tối đa 4.6GHz), đi kèm 16GB DDR4 3200MHz (1 khe, tối đa 64GB) và ổ cứng 512GB SSD M.2 PCIe NVMe. Máy đáp ứng trơn tru các tác vụ Word, Excel, PowerPoint, họp trực tuyến, học online và mở nhiều tab trình duyệt cùng lúc.\n\n## Card đồ họa\n\nIntel Iris Xe Graphics. Đồ họa tích hợp đủ để xem phim 4K, chỉnh sửa ảnh cơ bản và chơi các game nhẹ.\n\n## Màn hình\n\n14 inch Full HD (1920 x 1080), IPS, 60Hz, chống chói. Tấm nền IPS góc nhìn rộng kết hợp lớp phủ chống chói giúp làm việc lâu dưới đèn văn phòng hay ngoài trời vẫn dễ chịu.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 1.40 kg, màu Hồng (Beige Rose). Pin 3 cell 39.3Wh, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành Windows 11 Home bản quyền được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n1 x USB-C 3.2, 2 x USB-A 3.2, 1 x HDMI 1.4, 1 x đầu đọc thẻ microSD, 1 x jack 3.5mm. Kết nối không dây: Wi-Fi 6E, Bluetooth 5.3.\n\n## Phù hợp với\n\nHọc sinh, sinh viên, nhân viên văn phòng, giáo viên và gia đình cần một chiếc máy bền bỉ, dễ dùng với chi phí hợp lý.\n\n## Cam kết tại LAPSTORE