INSERT INTO product VALUES ('d5e30e13-77c5-4d2b-8663-8fb482f7e1ba', 'ACR-007', 'Acer Nitro V 15 ANV15-51 i5-13420H/8GB/512GB/RTX 2050/15.6\" 144Hz', 'Acer', '17990000.00', '19990000.00', '21', 'bcbc7029-3eec-4097-a7cb-233ad485346e', 'Intel Core i5-13420H (8 nhân 12 luồng, tối đa 4.6GHz)', '8GB DDR5 5200MHz (2 khe, tối đa 32GB)', '8', '512GB SSD M.2 PCIe Gen4 NVMe', '512', 'NVIDIA GeForce RTX 2050 4GB GDDR6', '15.6 inch Full HD (1920 x 1080), IPS, 144Hz', '3 cell 57Wh', '2.11 kg', 'Windows 11 Home bản quyền', '1 x Thunderbolt 4, 3 x USB-A 3.2, 1 x HDMI 2.1, 1 x RJ45 LAN, 1 x jack 3.5mm', 'Wi-Fi 6, Bluetooth 5.1', 'Đen (Obsidian Black)', '12', '0', 'Acer Nitro V 15 là laptop gaming rẻ nhất cửa hàng vẫn có màn hình 144Hz và RAM DDR5. Máy đáp ứng tốt các game online phổ biến tại Việt Nam như FC Online, Liên Minh Huyền Thoại, Valorant ở thiết lập cao.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Intel Core i5-13420H (8 nhân 12 luồng, tối đa 4.6GHz), đi kèm 8GB DDR5 5200MHz (2 khe, tối đa 32GB) và ổ cứng 512GB SSD M.2 PCIe Gen4 NVMe. Cấu hình này đủ sức chiến mượt các tựa game AAA lẫn eSports, đồng thời xử lý tốt livestream, dựng video và các tác vụ nặng khác.\n\n## Card đồ họa\n\nNVIDIA GeForce RTX 2050 4GB GDDR6. Card hỗ trợ công nghệ DLSS và Ray Tracing, tăng tốc khung hình khi chơi game và rút ngắn thời gian render, xuất video.\n\n## Màn hình\n\n15.6 inch Full HD (1920 x 1080), IPS, 144Hz. Tần số quét cao giúp mọi chuyển động mượt mà, mang lại lợi thế lớn trong các game bắn súng và đua xe tốc độ cao.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 2.11 kg, màu Đen (Obsidian Black). Pin 3 cell 57Wh, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành Windows 11 Home bản quyền được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n1 x Thunderbolt 4, 3 x USB-A 3.2, 1 x HDMI 2.1, 1 x RJ45 LAN, 1 x jack 3.5mm. Kết nối không dây: Wi-Fi 6, Bluetooth 5.1.\n\n## Phù hợp với\n\nGame thủ, streamer, sinh viên công nghệ thông tin và những ai cần một cỗ máy hiệu năng cao cho cả giải trí lẫn công việc nặng.\n\n## Cam kết tại LAPSTORE\n\nSản phẩm chính hãng mới 100%, nguyên seal. Bảo hành 12 tháng theo tiêu chuẩn nhà sản xuất, 1 đổi 1 trong 15 ngày nếu có lỗi phần cứng. Miễn phí giao hàng toàn quốc, hỗ trợ cài đặt phần mềm trọn đời và trả góp 0% qua thẻ tín dụng.', '/images/products/acr-007.jpg', '2026-10-24 21:19:13.212', '2026-10-24 21:19:13.212', '0');
