INSERT INTO product VALUES ('de1f2e7f-b514-446b-909c-19b38c1e8655', 'LEN-009', 'Lenovo Legion 5 16IRX9 i7-14650HX/16GB/1TB/RTX 4060/16\" WQXGA 165Hz', 'Lenovo', '37990000.00', '41990000.00', '8', 'bcbc7029-3eec-4097-a7cb-233ad485346e', 'Intel Core i7-14650HX (16 nhân 24 luồng, tối đa 5.2GHz)', '16GB DDR5 5600MHz (2 khe, tối đa 32GB)', '16', '1TB SSD M.2 PCIe Gen4 NVMe', '1024', 'NVIDIA GeForce RTX 4060 8GB GDDR6, TGP 140W', '16 inch WQXGA (2560 x 1600), IPS, 165Hz, 500 nits, 100% sRGB, Dolby Vision', '4 cell 80Wh, sạc nhanh Super Rapid Charge', '2.30 kg', 'Windows 11 Home bản quyền', '2 x USB-C 3.2 (DisplayPort), 3 x USB-A 3.2, 1 x HDMI 2.1, 1 x RJ45 LAN, 1 x jack 3.5mm', 'Wi-Fi 6E, Bluetooth 5.1', 'Xám (Luna Grey)', '24', '0', 'Legion 5 thế hệ 9 được nhiều reviewer đánh giá là laptop gaming cân bằng nhất: màn hình 2.5K 165Hz sáng 500 nits, bàn phím TrueStrike êm tay và hệ thống tản nhiệt Legion Coldfront 5.0 vận hành mát, ít ồn.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Intel Core i7-14650HX (16 nhân 24 luồng, tối đa 5.2GHz), đi kèm 16GB DDR5 5600MHz (2 khe, tối đa 32GB) và ổ cứng 1TB SSD M.2 PCIe Gen4 NVMe. Cấu hình này đủ sức chiến mượt các tựa game AAA lẫn eSports, đồng thời xử lý tốt livestream, dựng video và các tác vụ nặng khác.\n\n## Card đồ họa\n\nNVIDIA GeForce RTX 4060 8GB GDDR6, TGP 140W. Card hỗ trợ công nghệ DLSS và Ray Tracing, tăng tốc khung hình khi chơi game và rút ngắn thời gian render, xuất video.\n\n## Màn hình\n\n16 inch WQXGA (2560 x 1600), IPS, 165Hz, 500 nits, 100% sRGB, Dolby Vision. Tần số quét cao giúp mọi chuyển động mượt mà, mang lại lợi thế lớn trong các game bắn súng và đua xe tốc độ cao.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 2.30 kg, màu Xám (Luna Grey). Pin 4 cell 80Wh, sạc nhanh Super Rapid Charge, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành Windows 11 Home bản quyền được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n2 x USB-C 3.2 (DisplayPort), 3 x USB-A 3.2, 1 x HDMI 2.1, 1 x RJ45 LAN, 1 x jack 3.5mm. Kết nối không dây: Wi-Fi 6E, Bluetooth 5.1.\n\n## Phù hợp với\n\nGame thủ, streamer, sinh viên công nghệ thông tin và những ai cần một cỗ máy hiệu năng cao cho cả giải trí lẫn công việc nặng.\n\n## Cam kết tại LAPSTORE\n\nSản phẩm chính hãng mới 100%, nguyên seal. Bảo hành 24 tháng theo tiêu chuẩn nhà sản xuất, 1 đổi 1 trong 15 ngày nếu có lỗi phần cứng. Miễn phí giao hàng toàn quốc, hỗ trợ cài đặt phần mềm trọn đời và trả góp 0% qua thẻ tín dụng.', '/images/products/len-009.jpg', '2026-10-24 21:19:13.064', '2026-10-24 21:19:13.064', '0');
