yên seal. Bảo hành 12 tháng theo tiêu chuẩn nhà sản xuất, 1 đổi 1 trong 15 ngày nếu có lỗi phần cứng. Miễn phí giao hàng toàn quốc, hỗ trợ cài đặt phần mềm trọn đời và trả góp 0% qua thẻ tín dụng.', '/images/products/acr-002.jpg', '2026-10-24 21:19:13.174', '2026-10-24 21:19:13.174', '0');
INSERT INTO product VALUES ('feaca58b-1e44-4f55-83b3-7c90466617a3', 'HPQ-008', 'HP Victus 15-fa1000 i5-13420H/16GB/512GB/RTX 3050/15.6\" 144Hz', 'HP', '19990000.00', '22990000.00', '16', 'bcbc7029-3eec-4097-a7cb-233ad485346e', 'Intel Core i5-13420H (8 nhân 12 luồng, tối đa 4.6GHz)', '16GB DDR4 3200MHz (2 x 8GB)', '16', '512GB SSD M.2 PCIe NVMe', '512', 'NVIDIA GeForce RTX 3050 6GB GDDR6', '15.6 inch Full HD (1920 x 1080), IPS, 144Hz, 250 nits', '4 cell 70Wh', '2.29 kg', 'Windows 11 Home bản quyền', '1 x USB-C 3.2, 2 x USB-A 3.2, 1 x HDMI 2.1, 1 x RJ45 LAN, 1 x đầu đọc thẻ SD, 1 x jack 3.5mm', 'Wi-Fi 6, Bluetooth 5.3', 'Xanh đen (Performance Blue)', '12', '0', 'HP Victus 15 sở hữu thiết kế tối giản không quá \'hầm hố\', phù hợp cả khi mang lên lớp hay đến văn phòng. Phần mềm OMEN Gaming Hub cho phép ép xung, theo dõi nhiệt độ và tùy chỉnh hiệu năng dễ dàng.\n\n## Hiệu năng\n\nMáy được trang bị bộ vi xử lý Intel Core i5-13420H (8 nhân 12 luồng, tối đa 4.6GHz), đi kèm 16GB DDR4 3200MHz (2 x 8GB) và ổ cứng 512GB SSD M.2 PCIe NVMe. Cấu hình này đủ sức chiến mượt các tựa game AAA lẫn eSports, đồng thời xử lý tốt livestream, dựng video và các tác vụ nặng khác.\n\n## Card đồ họa\n\nNVIDIA GeForce RTX 3050 6GB GDDR6. Card hỗ trợ công nghệ DLSS và Ray Tracing, tăng tốc khung hình khi chơi game và rút ngắn thời gian render, xuất video.\n\n## Màn hình\n\n15.6 inch Full HD (1920 x 1080), IPS, 144Hz, 250 nits. Tần số quét cao giúp mọi chuyển động mượt mà, mang lại lợi thế lớn trong các game bắn súng và đua xe tốc độ cao.\n\n## Thiết kế & Pin\n\nMáy có trọng lượng 2.29 kg, màu Xanh đen (Performance Blue). Pin 4 cell 70Wh, đủ đáp ứng nhu cầu làm việc và học tập khi di chuyển. Hệ điều hành Windows 11 Home bản quyền được cài sẵn, mở hộp là dùng ngay.\n\n## Cổng kết nối\n\n1 x USB-C 3.2, 2 x USB-A 3.2, 1 x HDMI 2.1, 1 x RJ45 LAN, 1 x đầu đọc thẻ SD, 1 x jack 3.5mm. Kết nối không dây: Wi-Fi 6, Bluetooth 5.3.\n\n## Phù hợp với\n\nGame thủ, streamer, sinh viên công nghệ thông tin và những ai cần một cỗ máy hiệu năng cao cho cả giải trí lẫn công việc nặng.\n\n## Cam kết tại LAPSTORE\n\nSản phẩm chính hãng mới 100%, nguyên seal. Bảo hành 12 tháng theo tiêu chuẩn nhà sản xuất, 1 đổi 1 trong 15 ngày nếu có lỗi phần cứng. Miễn phí giao hàng toàn quốc, hỗ trợ cài đặt phần mềm trọn đời và trả góp 0% qua thẻ tín dụng.', '/images/products/hpq-008.jpg', '2026-10-24 21:19:13.143', '2026-10-25 05:43:10.612', '7');

-- ----------------------------
-- Table structure for `review`
-- ----------------------------
DROP TABLE IF EXISTS `review`;
CREATE TABLE `review` (
  `id` varchar(191) NOT NULL,
  `orderId` varchar(191) NOT NULL,
  `productId` varchar(191) NOT NULL,
  `userId` varchar(191) NOT NULL,
  `rating` int(11) NOT NULL DEFAULT 5,
  `comment` text DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `review_orderId_productId_key` (`orderId`,`productId`),
  KEY `review_productId_idx` (`productId`),
  KEY `review_userId_fkey` (`userId`),
  CONSTRAINT `review_orderId_fkey` FOREIGN KEY (`orderId`) REFERENCES `order` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `review_productId_fkey` FOREIGN KEY (`productId`) REFERENCES `product` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `review_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `user` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `review_rating_range` CHECK (`rating` between 1 and 5)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Records of review
-- ----------------------------

-- ----------------------------
-- Table structure for `reviewreply`
-- ----------------------------
DROP TABLE IF EXISTS `reviewreply`;
CREATE TABLE `reviewreply` (
  `id` varchar(191) NOT NULL,
  `reviewId` varchar(191) NOT NULL,
  `userId` varchar(191) NOT NULL,
  `content` text NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  KEY `reviewreply_reviewId_fkey` (`reviewId`),
  KEY `reviewreply_userId_fkey` (`userId`),
  CONSTRAINT `reviewreply_reviewId_fkey` FOREIGN KEY (`reviewId`) REFERENCES `review` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `reviewreply_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `user` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Records of reviewreply
-- ----------------------------

-- ----------------------------
-- Table structure for `user`
-- ----------------------------
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user` (
  `id` varchar(191) NOT NULL,
  `role` enum('ADMIN','USER') NOT NULL DEFAULT 'USER',
  `name` varchar(191) NOT NULL,
  `email` varchar(191) NOT NULL,
  `passwordHash` varchar(191) NOT NULL,
  `phoneNumber` varchar(191) DEFAULT NULL,
  `address` varchar(191) DEFAULT NULL,
  `points` int(11) NOT NULL DEFAULT 0,
  `rank` enum('BRONZE','SILVER','GOLD','PLATINUM') NOT NULL DEFAULT 'BRONZE',
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  `resetToken` varchar(191) DEFAULT NULL,
  `resetTokenExpiry` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_email_key` (`email`),
  UNIQUE KEY `user_resetToken_key` (`resetToken`),
  CONSTRAINT `user_points_non_negative` CHECK (`points` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

